//! Chunk 51, lead#1 (trace verifier): a direct return's collateral tail
//! (`lovejoin::direct_tail`) with a stranger's plain 5 ₳ listed before the
//! session's own collateral.
//!
//! The lead: `direct_tail` takes the first 5 ₳ row that fits the collateral
//! rule, whoever's it is, "so a stranger's plain 5 ₳ listed first is boxed and
//! the session's own collateral comes back unmixed".
//!
//! What this pins instead, and it passes on TREE: the tail's deposit spends
//! every ADA-only row at the account as one pool of coins, the session's own
//! collateral among them (as a payer), whichever 5 ₳ row comes first. Its
//! input set is the same in either order, it makes one 5 ₳ box (the wallet's),
//! and the return after it never sees the session's collateral (the deposit
//! spent it). What comes back directly is everything but that one box's 5 ₳
//! and the fees, so the stranger's 5 ₳ only adds to it. Lovelace has no
//! identity inside one transaction, so no order makes "the session's own"
//! 5 ₳ come back unmixed.
//!
//! It also prints where the tail's change goes in W1b's shape (a stranger's
//! 5 ₳ at base(session payment key, a stake key of the stranger's), listed
//! first), which is a different consequence of the same pick and is not
//! asserted here.

use blstrs::Scalar;
use pallas_addresses::{
    Address, Network, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_traverse::MultiEraTx;
use seedelf_core::eval::{self, Resolved};
use seedelf_core::lovejoin::{
    BoxValue, PoolBox, Protocol, ReferenceDatum, holder_address, mix_datum, templates,
};
use seedelf_crypto::cardano::{CardanoAccount, ONE_TIME_ACCOUNT, Role};
use seedelf_crypto::register::Register;
use seedelf_koios::koios::UtxoResponse;
use seedelf_wasm::api;
use seedelf_wasm::lovejoin::{self, OutRef, PoolRef};
use serde_json::{Value, json};
use std::collections::BTreeSet;

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

fn accounts() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, ONE_TIME_ACCOUNT).unwrap()
}

fn fixture() -> Value {
    serde_json::from_str(include_str!(
        "../../../seedelf-core/tests/fixtures/eval-preprod.json"
    ))
    .unwrap()
}

/// Preprod's parameters at epoch 315, with its V3 cost model (as lovejoin_test.rs).
fn params() -> Value {
    let cases = fixture()["cases"].as_array().unwrap().clone();
    let seedelf = cases
        .iter()
        .find(|c| c["name"].as_str().unwrap().starts_with("seedelf"))
        .unwrap();
    json!({
        "min_fee_a": 44, "min_fee_b": 155381, "coins_per_utxo_size": "4310",
        "key_deposit": "2000000", "price_mem": 0.0577, "price_step": 0.0000721,
        "min_fee_ref_script_cost_per_byte": 15,
        "cost_models": { "PlutusV3": seedelf["cost_model_v3"] },
    })
}

/// Session 0's account, base(payment 0/0, stake 2/0), on preprod.
fn session() -> String {
    api::one_time_address(&accounts(), true, 0)
        .unwrap()
        .to_bech32()
        .unwrap()
}

/// Session 0's payment key under a stake key of the stranger's choosing.
fn stranger_shape() -> String {
    let key = accounts().key_hash(Role::Receive, 0).unwrap();
    Address::Shelley(ShelleyAddress::new(
        Network::Testnet,
        ShelleyPaymentPart::key_hash(key),
        ShelleyDelegationPart::key_hash(pallas_crypto::hash::Hash::new([0x5a; 28])),
    ))
    .to_bech32()
    .unwrap()
}

/// A plain ADA-only row, as Koios lists one.
fn row(tx: u8, index: u64, address: &str, lovelace: u64) -> UtxoResponse {
    serde_json::from_value(json!({
        "tx_hash": hex::encode([tx; 32]), "tx_index": index, "address": address,
        "value": lovelace.to_string(), "stake_address": null, "payment_cred": "",
        "epoch_no": 0, "block_height": 0, "block_time": 0, "datum_hash": null,
        "inline_datum": null, "reference_script": null, "asset_list": [], "is_spent": false,
    }))
    .unwrap()
}

/// A box as Koios lists it at `mix_box`.
fn box_row(b: &PoolBox, protocol: &Protocol) -> UtxoResponse {
    serde_json::from_value(json!({
        "tx_hash": hex::encode(b.utxo.tx_hash), "tx_index": b.utxo.index,
        "address": protocol.mix_box_address().to_bech32().unwrap(),
        "value": protocol.denom.to_string(), "stake_address": null,
        "payment_cred": hex::encode(protocol.mix_box_hash),
        "epoch_no": 0, "block_height": 0, "block_time": 0, "datum_hash": null,
        "inline_datum": { "bytes": hex::encode(mix_datum(&b.a, &b.b)), "value": {} },
        "reference_script": null, "asset_list": [], "is_spent": false,
    }))
    .unwrap()
}

/// A 5 ₳ ADA pool as the worker names one (lovejoin_test.rs's `ada_pool_ref`).
fn ada_pool_ref() -> PoolRef {
    const SEED: &str = "5c6f327e511818805adb6b4e055a6b222f9f8706cfda3540bdb0e9bb0f6acc0b";
    const NFT_POLICY: &str = "c5852bb700034b0b259c9e237e58ffc5d022ce8f67600fbf32736e69";
    let lovelace = 5_000_000;
    let d = templates::derive(&hex::decode(SEED).unwrap().try_into().unwrap(), 2).unwrap();
    let datum = ReferenceDatum {
        box_value: BoxValue::ada(lovelace),
        max_fee: lovelace * 3 / 4,
        mix_box_hash: d.mix_box.hash,
        mix_logic_hash: d.mix_logic.hash,
        fee_hash: d.fee_contract.hash,
    };
    let holder = holder_address(true).to_bech32().unwrap();
    let at_holder = |mut row: UtxoResponse| {
        row.payment_cred = hex::encode(templates::REFERENCE_HOLDER_HASH);
        row
    };
    let mut reference = at_holder(row(0x7f, 0, &holder, 1_698_140));
    reference.asset_list = serde_json::from_value(json!([{
        "policy_id": NFT_POLICY, "asset_name": hex::encode("lovejoin"), "quantity": "1",
        "decimals": 0, "fingerprint": "",
    }]))
    .unwrap();
    reference.inline_datum =
        serde_json::from_value(json!({ "bytes": hex::encode(datum.encode()), "value": {} }))
            .unwrap();
    let script = |tx: u8, s: &templates::Script| {
        let mut row = at_holder(row(tx, 0, &holder, 20_000_000));
        row.reference_script = serde_json::from_value(json!({
            "hash": hex::encode(s.hash), "size": s.cbor.len(), "type": "plutusV3",
            "bytes": hex::encode(&s.cbor),
        }))
        .unwrap();
        row
    };
    PoolRef {
        reference,
        seed: OutRef {
            tx_hash: SEED.to_string(),
            tx_index: 2,
        },
        scripts: vec![script(0x7d, &d.mix_box), script(0x17, &d.mix_logic)],
    }
}

fn five() -> Protocol {
    lovejoin::protocol_of(true, Some(&ada_pool_ref())).unwrap()
}

/// Two other people's boxes in the 5 ₳ pool, for the tail's mix to draw.
fn others() -> Vec<UtxoResponse> {
    let pool = five();
    (0..2u8)
        .map(|i| {
            let owner = Register::create(Scalar::from(9_000u64 + u64::from(i)))
                .unwrap()
                .rerandomize()
                .unwrap();
            let point = |p: &str| -> [u8; 48] { hex::decode(p).unwrap().try_into().unwrap() };
            let mut hash = [0xa2; 32];
            hash[31] = i;
            box_row(
                &PoolBox {
                    utxo: Resolved {
                        tx_hash: hash,
                        index: 0,
                        output: vec![],
                    },
                    a: point(&owner.generator),
                    b: point(&owner.public_value),
                },
                &pool,
            )
        })
        .collect()
}

fn outref(u: &UtxoResponse) -> (String, u64) {
    (u.tx_hash.clone(), u.tx_index)
}

fn inputs(tx: &MultiEraTx) -> BTreeSet<(String, u64)> {
    tx.inputs()
        .iter()
        .map(|i| (hex::encode(**i.hash()), i.index()))
        .collect()
}

/// What one direct return with the tail shows.
struct Seen {
    deposit_inputs: BTreeSet<(String, u64)>,
    deposit_fee: u64,
    deposit_change: u64,
    deposit_change_address: Vec<u8>,
    mix_change_address: Vec<u8>,
}

/// Session 0's direct return of `utxos`, in the order given, its collateral
/// into the 5 ₳ pool, and every check the lead's claim turns on.
fn direct_return(sk: Scalar, utxos: Vec<UtxoResponse>, own: &[String]) -> Seen {
    let pool = five();
    let result = api::session_return(
        &accounts(),
        sk,
        api::SessionReturnRequest {
            network: "preprod".into(),
            params: params(),
            index: 0,
            utxos: utxos.clone(),
            merge: vec![],
            own: own.to_vec(),
            collateral_pool: Some(ada_pool_ref()),
            collateral_boxes: others(),
            rewards: Default::default(),
        },
    )
    .unwrap();
    let tail = result.tail.as_ref().expect("the collateral's tail is built");
    let kinds: Vec<&str> = tail.txs.iter().map(|t| t.kind.as_str()).collect();
    assert_eq!(kinds, vec!["deposit", "mix"]);

    // The deposit spends every ADA-only row at the account: whichever 5 ₳ was
    // picked, the other is a payer, so the session's own collateral is spent here.
    let deposited = hex::decode(&tail.txs[0].tx_cbor).unwrap();
    let d = MultiEraTx::decode(&deposited).unwrap();
    let every_row: BTreeSet<(String, u64)> = utxos.iter().map(outref).collect();
    assert_eq!(inputs(&d), every_row, "the deposit spends every row");

    // One box, 5 ₳ of ADA alone, the wallet's own.
    let mix_box = pool.mix_box_address().to_vec();
    let boxes: Vec<usize> = d
        .outputs()
        .iter()
        .enumerate()
        .filter(|(_, o)| o.address().unwrap().to_vec() == mix_box)
        .map(|(i, _)| i)
        .collect();
    assert_eq!(boxes, vec![tail.tail.boxed.tx_index as usize], "one box");
    let out = &d.outputs()[boxes[0]];
    assert_eq!(out.value().coin(), 5_000_000);
    assert!(out.value().assets().is_empty());
    let resolved = eval::resolve_outputs(&deposited).unwrap();
    assert!(
        PoolBox::from_resolved(resolved[boxes[0]].clone(), &pool)
            .unwrap()
            .is_owned(&sk)
    );
    let change = d
        .outputs()
        .iter()
        .enumerate()
        .find(|(i, _)| *i != boxes[0])
        .map(|(_, o)| o.clone())
        .expect("the deposit's change");
    assert_eq!(d.outputs().len(), 2, "the box and the change, nothing else");

    // The mix takes that box and the deposit's change.
    let mixed = hex::decode(&tail.txs[1].tx_cbor).unwrap();
    let m = MultiEraTx::decode(&mixed).unwrap();
    assert!(inputs(&m).contains(&(tail.tail.boxed.tx_hash.clone(), tail.tail.boxed.tx_index)));
    assert!(m.inputs().iter().any(|i| *i.hash() == d.hash()));
    let mix_change = m
        .outputs()
        .iter()
        .find(|o| o.address().unwrap().to_vec() != mix_box)
        .map(|o| o.clone())
        .expect("the mix's change");

    // The return never sees any row at the account, the session's own
    // collateral included: it sweeps the mix's change alone.
    let back_bytes = hex::decode(&result.tx_cbor).unwrap();
    let back = MultiEraTx::decode(&back_bytes).unwrap();
    let back_inputs = inputs(&back);
    assert!(every_row.iter().all(|r| !back_inputs.contains(r)));
    assert!(back.inputs().iter().any(|i| *i.hash() == m.hash()));
    assert_eq!(result.inputs, 1, "the mix's change alone");

    // Everything but one box's 5 ₳ and the fees comes back.
    let total: u64 = utxos.iter().map(|u| u.value.parse::<u64>().unwrap()).sum();
    let fee: u64 = result.fee.parse().unwrap();
    let tail_fee: u64 = tail.tail.fee.parse().unwrap();
    assert_eq!(
        result.lovelace.parse::<u64>().unwrap(),
        total - 5_000_000 - tail_fee - fee
    );

    Seen {
        deposit_inputs: inputs(&d),
        deposit_fee: tail.txs[0].fee.parse().unwrap(),
        deposit_change: change.value().coin(),
        deposit_change_address: change.address().unwrap().to_vec(),
        mix_change_address: mix_change.address().unwrap().to_vec(),
    }
}

#[test]
fn a_strangers_5_ada_listed_first_boxes_nothing_but_5_ada_of_the_same_deposit() {
    let sk = Scalar::from(51_001u64);
    let at = session();
    // The funding pays the account its amount and its 5 ₳ collateral, both
    // outputs of one transaction (privacy.md, "The funding's shape marks it").
    let funding = 0x11u8;
    let own = vec![hex::encode([funding; 32])];
    let own_amount = row(funding, 0, &at, 20_000_000);
    let own_collateral = row(funding, 1, &at, 5_000_000);
    // A stranger's plain 5 ₳ to the session's own address.
    let stranger = row(0xee, 0, &at, 5_000_000);

    // No stranger: the session's own collateral is the tail's.
    let alone = direct_return(sk, vec![own_amount.clone(), own_collateral.clone()], &own);

    // The lead's case: the stranger's 5 ₳ listed first, then the other way round.
    let first = direct_return(
        sk,
        vec![stranger.clone(), own_amount.clone(), own_collateral.clone()],
        &own,
    );
    let last = direct_return(
        sk,
        vec![own_collateral.clone(), own_amount.clone(), stranger.clone()],
        &own,
    );
    // The same deposit whichever 5 ₳ comes first: the same inputs, the same
    // fee, the same 5 ₳ box beside the same change.
    assert_eq!(first.deposit_inputs, last.deposit_inputs);
    assert_eq!(
        first.deposit_inputs,
        [&stranger, &own_amount, &own_collateral]
            .into_iter()
            .map(outref)
            .collect::<BTreeSet<_>>()
    );
    assert_eq!(first.deposit_fee, last.deposit_fee);
    assert_eq!(first.deposit_change, last.deposit_change);
    // Its change holds the stranger's 5 ₳ beside what it held alone, less the
    // extra input's few bytes of fee.
    assert!(first.deposit_change > alone.deposit_change);
    assert!(first.deposit_change + first.deposit_fee - (alone.deposit_change + alone.deposit_fee) == 5_000_000);
    let session_bytes = Address::from_bech32(&at).unwrap().to_vec();
    for seen in [&alone, &first, &last] {
        assert_eq!(seen.deposit_change_address, session_bytes);
        assert_eq!(seen.mix_change_address, session_bytes);
    }

    // W1b's shape: the stranger's 5 ₳ under the session's payment key and a
    // stake key of its own, listed first. The lead's claim fails the same way.
    let shaped = row(0xef, 0, &stranger_shape(), 5_000_000);
    let w1b = direct_return(
        sk,
        vec![shaped.clone(), own_amount.clone(), own_collateral.clone()],
        &own,
    );
    assert!(w1b.deposit_inputs.contains(&outref(&own_collateral)));
    // Where its change goes, for the record (W1b's second point, not lead#1's).
    let stranger_bytes = Address::from_bech32(&stranger_shape()).unwrap().to_vec();
    eprintln!(
        "r51 lead#1, W1b's shape listed first: deposit change at the session's address: {}, \
         at the stranger's base(session key, stranger stake): {}; mix change at the session's: {}, \
         at the stranger's: {}",
        w1b.deposit_change_address == session_bytes,
        w1b.deposit_change_address == stranger_bytes,
        w1b.mix_change_address == session_bytes,
        w1b.mix_change_address == stranger_bytes,
    );
}
